"""Shared launch orchestration for fixed-map planning and navigation."""

from pathlib import Path

from ament_index_python.packages import get_package_share_directory
from launch import LaunchDescription
from launch.actions import DeclareLaunchArgument, EmitEvent, RegisterEventHandler
from launch.conditions import IfCondition
from launch.event_handlers import OnProcessExit
from launch.events import Shutdown
from launch.substitutions import LaunchConfiguration
from launch_ros.actions import Node
from launch_ros.parameter_descriptions import ParameterValue

from navigation_pkg.scene import marker_pose

_PACKAGE_NAME = "navigation_pkg"


def generate_bringup(*, execute_path: bool) -> LaunchDescription:
    """Create the AMCL, planning, and optional path-execution launch graph."""
    share_directory = Path(get_package_share_directory(_PACKAGE_NAME))
    params_file = LaunchConfiguration("params_file")
    start_pose = marker_pose("start_marker")
    managed_nodes = ["map_server", "amcl", "planner_server"]

    map_server = Node(
        package="nav2_map_server",
        executable="map_server",
        name="map_server",
        parameters=[
            params_file,
            {
                "yaml_filename": ParameterValue(
                    LaunchConfiguration("map"), value_type=str
                )
            },
        ],
        output="screen",
    )
    amcl = Node(
        package="nav2_amcl",
        executable="amcl",
        name="amcl",
        parameters=[
            params_file,
            {
                "initial_pose.x": start_pose[0],
                "initial_pose.y": start_pose[1],
                "initial_pose.z": 0.0,
                "initial_pose.yaw": start_pose[5],
            },
        ],
        output="screen",
    )
    planning_map = Node(
        package=_PACKAGE_NAME,
        executable="planning_map_node",
        name="planning_map_node",
        parameters=[{"use_sim_time": True}],
        output="screen",
    )
    planner = Node(
        package="nav2_planner",
        executable="planner_server",
        name="planner_server",
        parameters=[params_file],
        output="screen",
    )
    controller = None
    if execute_path:
        managed_nodes.append("controller_server")
        controller = Node(
            package="nav2_controller",
            executable="controller_server",
            name="controller_server",
            parameters=[params_file],
            output="screen",
        )

    lifecycle_manager = Node(
        package="nav2_lifecycle_manager",
        executable="lifecycle_manager",
        name="lifecycle_manager_navigation",
        parameters=[
            {
                "use_sim_time": True,
                "autostart": True,
                "node_names": managed_nodes,
            }
        ],
        output="screen",
    )
    mission = Node(
        package=_PACKAGE_NAME,
        executable="navigation_task_node",
        name="navigation_task_node",
        parameters=[
            {
                "use_sim_time": True,
                "execute_path": execute_path,
                "planner_id": ParameterValue(
                    LaunchConfiguration("planner_id"), value_type=str
                ),
            }
        ],
        output="screen",
    )

    actions = [
        DeclareLaunchArgument(
            "map",
            default_value=str(share_directory / "maps" / "map.yaml"),
            description="Map YAML used by map_server and AMCL",
        ),
        DeclareLaunchArgument(
            "params_file",
            default_value=str(share_directory / "config" / "nav2.yaml"),
            description="Nav2 parameter file containing plugin selections",
        ),
        DeclareLaunchArgument(
            "planner_id",
            default_value="GridBased",
            description="Configured planner plugin ID passed to the one-shot mission",
        ),
        DeclareLaunchArgument(
            "rviz",
            default_value="true",
            choices=["true", "false"],
            description="Display navigation state in RViz",
        ),
    ]
    if controller is not None:
        actions.extend(
            [
                RegisterEventHandler(
                    OnProcessExit(
                        target_action=controller,
                        on_exit=[
                            EmitEvent(
                                event=Shutdown(
                                    reason="Navigation controller exited unexpectedly"
                                )
                            )
                        ],
                    )
                ),
                RegisterEventHandler(
                    OnProcessExit(
                        target_action=mission,
                        on_exit=[
                            EmitEvent(
                                event=Shutdown(
                                    reason="Navigation mission exited unexpectedly"
                                )
                            )
                        ],
                    )
                ),
            ]
        )
    actions.extend([map_server, amcl, planning_map, planner])
    if controller is not None:
        actions.append(controller)
    actions.extend(
        [
            lifecycle_manager,
            mission,
            Node(
                package="rviz2",
                executable="rviz2",
                arguments=["-d", str(share_directory / "config" / "navigation.rviz")],
                parameters=[{"use_sim_time": True}],
                condition=IfCondition(LaunchConfiguration("rviz")),
                output="screen",
            ),
        ]
    )
    return LaunchDescription(actions)
